import { useMemo, useState } from 'react'
import { useWidth } from './hooks'
import { layoutHeat, type Cell, type Day } from './heat'
import { cx } from './util'

export type ActivityHeatmapProps = { title: string; days: Day[]; weeks?: number; noun?: string; className?: string }

const GAP = 3
const LEFT = 30
const TOP = 20
const DAYS = ['Mon', '', 'Wed', '', 'Fri', '', '']

/** A calendar of activity. Colour is the day's quartile among active days. A red mark means a guarantee was breached that day. */
export function ActivityHeatmap({ title, days, weeks = 26, noun = 'events', className }: ActivityHeatmapProps) {
  const layout = useMemo(() => layoutHeat(days, weeks), [days, weeks])
  const [hover, setHover] = useState<Cell | null>(null)
  const [ref, avail] = useWidth<HTMLDivElement>(760)
  const CELL = Math.max(10, Math.min(22, Math.floor((avail - 36 - LEFT) / Math.max(layout.weeks, 1)) - GAP))
  const width = LEFT + layout.weeks * (CELL + GAP)
  const height = TOP + 7 * (CELL + GAP)
  const breaches = layout.cells.filter((c) => c.inRange && c.breaches > 0).length
  return (
    <section className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <h3 className="ol-title" style={{ margin: 0 }}>{title}</h3>
        <dl className="ol-figs" aria-label="Summary">
          <div><dt>{noun}</dt><dd>{layout.total.toLocaleString('en')}</dd></div>
          <div data-bad={breaches > 0}><dt>{breaches === 1 ? 'day with a breach' : 'days with a breach'}</dt><dd>{breaches}</dd></div>
          <div><dt>longest run without one, in days</dt><dd>{layout.breachFreeRun}</dd></div>
        </dl>
      </div>
      <div ref={ref} className="ol-scroll" style={{ position: 'relative' }}>
        <svg width={width} height={height} role="img" aria-label={`${title}. ${layout.total} ${noun}, ${breaches} days with a breach.`}>
          {layout.months.map((m) => <text key={m.week} x={LEFT + m.week * (CELL + GAP)} y={11} className="ol-axis-text">{m.label}</text>)}
          {DAYS.map((d, i) => (d ? <text key={d} x={0} y={TOP + i * (CELL + GAP) + CELL - 2} className="ol-axis-text">{d}</text> : null))}
          {layout.cells.map((c) => {
            if (!c.inRange) return null
            const cx0 = LEFT + c.week * (CELL + GAP)
            const cy0 = TOP + c.weekday * (CELL + GAP)
            return (
              <g key={c.date} onPointerEnter={() => setHover(c)} onPointerLeave={() => setHover(null)}>
                <rect x={cx0} y={cy0} width={CELL} height={CELL} rx={3} className="ol-hcell" data-level={c.level} data-hover={hover?.date === c.date} />
                {c.breaches > 0 && <circle cx={cx0 + CELL - 3} cy={cy0 + 3} r={3} className="ol-hbreach" />}
              </g>
            )
          })}
        </svg>
        {hover && (
          <div className="ol-tip" role="tooltip" style={{ left: Math.min(LEFT + hover.week * (CELL + GAP) + 18, width - 180), top: TOP + hover.weekday * (CELL + GAP) + 22 }}>
            <strong>{hover.date}</strong>
            <div className="ol-mono">{hover.count} {noun}</div>
            {hover.breaches > 0 && <div style={{ color: 'var(--ol-bad)' }}>{hover.breaches} {hover.breaches === 1 ? 'breach' : 'breaches'}</div>}
          </div>
        )}
      </div>
      <div className="ol-hlegend" aria-hidden="true">Less {[0, 1, 2, 3, 4].map((l) => <i key={l} className="ol-hcell-sw" data-level={l} />)} More <span style={{ marginLeft: 12 }}><i className="ol-hbreach-sw" /> breach</span></div>
    </section>
  )
}

// Calendar heatmap layout: weeks as columns, Monday first, and quartile levels for the colour.

export type Day = { date: string; count: number; breaches?: number }
export type Cell = { date: string; count: number; breaches: number; level: 0 | 1 | 2 | 3 | 4; week: number; weekday: number; inRange: boolean }

const DAY = 86_400_000
const utc = (iso: string) => Date.UTC(+iso.slice(0, 4), +iso.slice(5, 7) - 1, +iso.slice(8, 10))
const iso = (ms: number) => new Date(ms).toISOString().slice(0, 10)
/** Monday = 0 ... Sunday = 6. */
const weekday = (ms: number) => (new Date(ms).getUTCDay() + 6) % 7

/** Level 0 is no activity. The rest are quartiles of the days that had any, so one huge day cannot flatten the rest. */
export function levelsFor(counts: number[]): (n: number) => 0 | 1 | 2 | 3 | 4 {
  const nz = counts.filter((c) => c > 0).sort((a, b) => a - b)
  if (!nz.length) return () => 0
  const q = (p: number) => nz[Math.min(nz.length - 1, Math.floor(p * nz.length))]!
  const [a, b, c] = [q(0.25), q(0.5), q(0.75)]
  return (n) => (n <= 0 ? 0 : n <= a ? 1 : n <= b ? 2 : n <= c ? 3 : 4)
}

export function layoutHeat(days: Day[], weeks = 26): { cells: Cell[]; weeks: number; months: { week: number; label: string }[]; total: number; busiest: Day | null; breachFreeRun: number } {
  if (!days.length) return { cells: [], weeks: 0, months: [], total: 0, busiest: null, breachFreeRun: 0 }
  const byDate = new Map(days.map((d) => [d.date, d]))
  const last = Math.max(...days.map((d) => utc(d.date)))
  const lastWeekStart = last - weekday(last) * DAY
  const firstWeekStart = lastWeekStart - (weeks - 1) * 7 * DAY
  const level = levelsFor(days.filter((d) => utc(d.date) >= firstWeekStart && utc(d.date) <= last).map((d) => d.count))
  const cells: Cell[] = []
  for (let w = 0; w < weeks; w++) {
    for (let wd = 0; wd < 7; wd++) {
      const ms = firstWeekStart + (w * 7 + wd) * DAY
      const date = iso(ms)
      const d = byDate.get(date)
      cells.push({ date, count: d?.count ?? 0, breaches: d?.breaches ?? 0, level: level(d?.count ?? 0), week: w, weekday: wd, inRange: ms <= last })
    }
  }
  const months: { week: number; label: string }[] = []
  let prev = -1
  for (let w = 0; w < weeks; w++) {
    const m = new Date(firstWeekStart + w * 7 * DAY).getUTCMonth()
    if (m !== prev) {
      months.push({ week: w, label: new Date(firstWeekStart + w * 7 * DAY).toLocaleString('en', { month: 'short', timeZone: 'UTC' }) })
      prev = m
    }
  }
  const inView = cells.filter((c) => c.inRange)
  const busiest = inView.reduce<Cell | null>((best, c) => (c.count > (best?.count ?? 0) ? c : best), null)
  // Longest run of days with no breach, counted over days that fall in the window and up to the last date.
  let run = 0
  let best = 0
  for (const c of inView) {
    run = c.breaches > 0 ? 0 : run + 1
    best = Math.max(best, run)
  }
  return { cells, weeks, months, total: inView.reduce((a, c) => a + c.count, 0), busiest: busiest && busiest.count > 0 ? { date: busiest.date, count: busiest.count, breaches: busiest.breaches } : null, breachFreeRun: best }
}
